Yes, you can use Natural Language Processing (NLP) techniques to classify a sentence as descriptive or analytical. 
In your example, the sentence "80% of the survey participants use public transportation" is descriptive because it simply describes a fact or observation. 
Here is an example C# code using the Stanford CoreNLP library to classify a sentence as descriptive or analytical:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using edu.stanford.nlp.pipeline;
using edu.stanford.nlp.ling;
using edu.stanford.nlp.util;
namespace NLPExample
{
    class Program
    {
        static void Main(string[] args)
        {
            string sentence = "80% of the survey participants use public transportation";
            var props = new Properties();
            props.setProperty("annotators", "tokenize, ssplit, pos, lemma, parse, sentiment");
            var pipeline = new StanfordCoreNLP(props);
            var annotation = new Annotation(sentence);
            pipeline.annotate(annotation);
            var sentences = annotation.get(typeof(CoreAnnotations.SentencesAnnotation)) as ArrayList;
            var tokens = sentences[0].get(typeof(CoreAnnotations.TokensAnnotation)) as ArrayList;
            var lastToken = tokens[tokens.Count - 1] as CoreLabel;
            var pos = lastToken.get(typeof(CoreAnnotations.PartOfSpeechAnnotation)) as string;
            if (pos.StartsWith("JJ"))
            {
                Console.WriteLine("The sentence is analytical.");
            }
            else
            {
                Console.WriteLine("The sentence is descriptive.");
            }
        }
    }
}
```
This code uses the Stanford CoreNLP library to annotate the input sentence with various linguistic information, including part-of-speech (POS) tags. It then checks the POS tag of the last token in the sentence to determine whether it is an adjective (which would indicate an analytical sentence) or not (which would indicate a descriptive sentence).

One way to sort the array in-place without using any sort function is to implement the selection sort algorithm. Here's an example C++ code:
```
#include <iostream>
using namespace std;
void selectionSort(int arr[], int n) {
    int i, j, minIndex, temp;
    for (i = 0; i < n - 1; i++) {
        minIndex = i;
        for (j = i + 1; j < n; j++) {
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }
        temp = arr[minIndex];
        arr[minIndex] = arr[i];
        arr[i] = temp;
    }
}
int main() {
    int arr[] = {5, 7, 3, 9, 10, 1};
    int n = sizeof(arr) / sizeof(arr[0]);
    selectionSort(arr, n);
    cout << "Sorted array: ";
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    return 0;
}
```
The selection sort algorithm works by repeatedly finding the minimum element from the unsorted part of the array and placing it at the beginning of the sorted part. In this implementation, we use two nested loops to iterate over the array and find the minimum element. We then swap the minimum element with the current element at the beginning of the sorted part of the array. This process is repeated until the entire array is sorted.

