    abstract class Shape
    {
        public abstract void SetMeasurements();
        public abstract void DisplayMeasurements();
        public abstract double CalculateArea();
    }
    class Circle : Shape
    {
        private double radius;
        public override void SetMeasurements()
        {
            Console.Write("\nEnter the radius of the circle: ");
            string input = Console.ReadLine();
            if (!double.TryParse(input, out radius) || radius < 0)
            {
                throw new Exception("Invalid input. Please enter a non-negative number.");
            }
        }
        public override void DisplayMeasurements()
        {
            Console.WriteLine("Radius: {0:F2}", radius);
        }
        public override double CalculateArea()
        {
            return Math.PI * radius * radius;
        }
    }
    class Square : Shape
    {
        private double side;
        public override void SetMeasurements()
        {
            Console.Write("\nEnter the length of a side of the square: ");
            string input = Console.ReadLine();
            if (!double.TryParse(input, out side) || side < 0)
            {
                throw new Exception("Invalid input. Please enter a non-negative number.");
            }
        }
        public override void DisplayMeasurements()
        {
            Console.WriteLine("Side length: {0:F2}", side);
        }
        public override double CalculateArea()
        {
            return side * side;
        }
    }
    class Triangle : Shape
    {
