To make a request to the Google Places API in Go to find the best Mexican restaurant in San Francisco, you can use the following parameters:
- `location`: the latitude and longitude of San Francisco
- `radius`: the radius of the search area (in meters)
- `type`: the type of place you're looking for (in this case, "mexican restaurant")
- `key`: your API key
Here's an example of the code you can use to make this request in Go:
```
package main
import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
)
func main() {
	url := "https://maps.googleapis.com/maps/api/place/nearbysearch/json?location=37.7749,-122.4194&radius=5000&type=mexican%20restaurant&key=YOUR_API_KEY"
	resp, err := http.Get(url)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		panic(err)
	}
	var data map[string]interface{}
	err = json.Unmarshal(body, &data)
	if err != nil {
		panic(err)
	}
	results := data["results"].([]interface{})
	for _, result := range results {
		resultMap := result.(map[string]interface{})
		name := resultMap["name"].(string)
		location := resultMap["geometry"].(map[string]interface{})["location"].(map[string]interface{})
		lat := location["lat"].(float64)
		lng := location["lng"].(float64)
		rating := resultMap["rating"].(float64)
		reviews := resultMap["user_ratings_total"].(float64)
		fmt.Printf("Name: %s\nLocation: %f,%f\nRating: %f\nReviews: %f\n\n", name, lat, lng, rating, reviews)
	}
}
```
