```
import AVFoundation
class ShoeTyingTutorialViewController: UIViewController {

    var audioPlayer: AVAudioPlayer?

    func playAudioInstruction(instruction: String) {
        let path = Bundle.main.path(forResource: instruction, ofType: "mp3")!
        let url = URL(fileURLWithPath: path)

