```java
import java.io.File;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
public class PlaylistCreator {

    public static void main(String[] args) {
        try {
            // Load the XML file
            File xmlFile = new File("love_songs.xml");
            DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
            Document doc = dBuilder.parse(xmlFile);
            doc.getDocumentElement().normalize();

            // Get all the songs from the XML file
            NodeList nodeList = doc.getElementsByTagName("song");
            List<Song> songs = new ArrayList<Song>();
            for (int i = 0; i < nodeList.getLength(); i++) {
                Element songElement = (Element) nodeList.item(i);
                String title = songElement.getElementsByTagName("title").item(0).getTextContent();
                String artist = songElement.getElementsByTagName("artist").item(0).getTextContent();
                String genre = songElement.getElementsByTagName("genre").item(0).getTextContent();
                int year = Integer.parseInt(songElement.getElementsByTagName("year").item(0).getTextContent());
                double rating = Double.parseDouble(songElement.getElementsByTagName("rating").item(0).getTextContent());
                Song song = new Song(title, artist, genre, year, rating);
                songs.add(song);
            }

            // Sort the songs by rating in descending order
            Collections.sort(songs, Collections.reverseOrder());

            // Create a playlist of the top 10 most romantic songs
            List<Song> playlist = new ArrayList<Song>();
            for (int i = 0; i < 10; i++) {
                playlist.add(songs.get(i));
            }

            // Print the playlist
            System.out.println("Top 10 most romantic songs:");
            for (int i = 0; i < playlist.size(); i++) {
                System.out.println((i+1) + ". " + playlist.get(i).getTitle() + " - " + playlist.get(i).getArtist());
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

}
