#include <iostream>
#include <unordered_map>
#include <vector>
#include <algorithm>
#include <nlohmann/json.hpp>
using json = nlohmann::json;
int main() {
    std::unordered_map<std::string, std::string> objects = {
        {"computer", "electronic device used for processing data"},
        {"car", "vehicle used for transportation"},
        {"shoe", "footwear worn for protection and comfort"},
        {"chair", "furniture used for sitting"},
        {"phone", "refurbished electronic device"},
        {"book", "newly published novel"}
    };

    std::vector<std::pair<std::string, std::string>> used_objects, new_objects, refurbished_objects;

    for(const auto& object : objects) {
        if(object.second.find("used") != std::string::npos) {
            used_objects.push_back(object);
        }
        else if(object.second.find("new") != std::string::npos) {
            new_objects.push_back(object);
        }
        else if(object.second.find("refurbished") != std::string::npos) {
            refurbished_objects.push_back(object);
        }
    }

    json j;
    j["Used Objects"] = json::object();
    j["New Objects"] = json::object();
    j["Refurbished Objects"] = json::object();

    for(const auto& object : used_objects) {
        j["Used Objects"][object.first] = object.second;
    }
    for(const auto& object : new_objects) {
        j["New Objects"][object.first] = object.second;
    }
    for(const auto& object : refurbished_objects) {
        j["Refurbished Objects"][object.first] = object.second;
    }

