    // Create lists to store adjectives
    std::vector<std::string> taste_adjectives;
    std::vector<std::string> texture_adjectives;
    std::vector<std::string> appearance_adjectives;
    // Loop through tagged tokens and extract adjectives
    for (int i = 0; i < PyList_Size(pos_tags); i++) {
        PyObject* token_pos = PyList_GetItem(pos_tags, i);
        PyObject* token = PyTuple_GetItem(token_pos, 0);
        PyObject* pos = PyTuple_GetItem(token_pos, 1);
        std::string token_str = PyUnicode_AsUTF8(token);
        std::string pos_str = PyUnicode_AsUTF8(pos);
        if (pos_str == "JJ") {
            if (token_str == "sweet" || token_str == "creamy" || token_str == "tangy") {
                taste_adjectives.push_back(token_str);
            }
            else if (token_str == "smooth") {
                texture_adjectives.push_back(token_str);
            }
            else if (token_str == "ripe" || token_str == "yellow") {
                appearance_adjectives.push_back(token_str);
            }
        }
    }
    // Print adjectives
    std::cout << "Taste adjectives:" << std::endl;
    for (auto adj : taste_adjectives) {
        std::cout << "- " << adj << std::endl;
    }
    std::cout << std::endl;
    std::cout << "Texture adjectives:" << std::endl;
    for (auto adj : texture_adjectives) {
        std::cout << "- " << adj << std::endl;
    }
    std::cout << std::endl;
    std::cout << "Appearance adjectives:" << std::endl;
    for (auto adj : appearance_adjectives) {
        std::cout << "- " << adj << std::endl;
    }
    std::cout << std::endl;
    // Clean up
    Py_DECREF(nltk_module);
    Py_DECREF(tokenizer);
    Py_DECREF(tokens);
    Py_DECREF(pos_tag);
    Py_DECREF(pos_tags);
    Py_Finalize();
    return 0;
}
```
