#include <iostream>
#include <vector>
#include <algorithm>
struct Animal {
    std::string name;
    std::string species;
    std::string notes;
};
void addAnimal(std::vector<Animal>& animals, std::string name, std::string species, std::string notes) {
    Animal newAnimal;
    newAnimal.name = name;
    newAnimal.species = species;
    newAnimal.notes = notes;
    animals.push_back(newAnimal);
}
void updateAnimal(std::vector<Animal>& animals, std::string name, std::string species, std::string notes) {
    for (auto& animal : animals) {
        if (animal.name == name && animal.species == species) {
            animal.notes = notes;
        }
    }
}
std::vector<Animal> searchAnimals(std::vector<Animal>& animals, std::string searchTerm) {
    std::vector<Animal> searchResults;
    for (auto& animal : animals) {
        if (animal.name == searchTerm || animal.species == searchTerm) {
            searchResults.push_back(animal);
        }
    }
    return searchResults;
}
