```
// Define the grocery list
const groceryList = [
  { name: 'Apples', price: 1.99 },
  { name: 'Bananas', price: 0.99 },
  { name: 'Milk', price: 2.49 },
  { name: 'Bread', price: 1.99 },
  { name: 'Eggs', price: 3.49 }
];
// Define the budget plan
const budgetPlan = {
  totalBudget: 20,
  remainingBudget: 20,
  itemsBought: []
};
// Function to add an item to the grocery list
function addItem(name, price) {
  groceryList.push({ name, price });
}
// Function to remove an item from the grocery list
function removeItem(name) {
  const index = groceryList.findIndex(item => item.name === name);
  if (index !== -1) {
    groceryList.splice(index, 1);
  }
}
// Function to suggest cheaper alternatives for an item
function suggestCheaperAlternatives(name) {
  const item = groceryList.find(item => item.name === name);
  if (item) {
    const cheaperAlternatives = groceryList.filter(item => item.price < item.price);
    return cheaperAlternatives;
  }
  return null;
}
// Function to update the budget plan when an item is bought
function buyItem(name) {
  const item = groceryList.find(item => item.name === name);
  if (item && budgetPlan.remainingBudget >= item.price) {
    budgetPlan.remainingBudget -= item.price;
    budgetPlan.itemsBought.push(item);
    return true;
  }
  return false;
}
