The most important distinguishing factor between mammals and non-mammals is whether or not they produce milk to feed their young. We can use this factor to create the first split in our decision tree. 
We can then use the other characteristics such as number of legs and whether or not they lay eggs to further refine the decision tree. For example, if an animal produces milk and has four legs, it is likely a mammal. If an animal does not produce milk and has wings, it is likely a bird. 
Here is an example of Go code that demonstrates how to construct and implement a decision tree using the given dataset:
```go
package main
import (
    "fmt"
)
type Animal struct {
    Species   string
    Legs      int
    LayEggs   bool
    IsMammal  bool
}
func main() {
    // Create dataset
    dataset := []Animal{
        {"Dog", 4, false, true},
        {"Snake", 0, true, false},
        {"Cat", 4, false, true},
        {"Bird", 2, true, false},
        {"Cow", 4, false, true},
        {"Frog", 4, true, false},
        {"Fish", 0, true, false},
        {"Elephant", 4, false, true},
        {"Lizard", 4, true, false},
        {"Bat", 2, false, true},
    }
    // Build decision tree
    tree := buildDecisionTree(dataset)
    // Test decision tree
    animal1 := Animal{"Horse", 4, false, true}
    animal2 := Animal{"Fish", 0, true, false}
    animal3 := Animal{"Kangaroo", 2, false, true}
    fmt.Println("Animal 1 is a mammal:", classifyAnimal(animal1, tree))
    fmt.Println("Animal 2 is a mammal:", classifyAnimal(animal2, tree))
    fmt.Println("Animal 3 is a mammal:", classifyAnimal(animal3, tree))
}
func buildDecisionTree(dataset []Animal) *node {
    // Create root node
    root := &node{}
    // Split on whether or not animal is a mammal
    root.split = "IsMammal"
    root.children = make(map[interface{}]*node)
    for _, animal := range dataset {
        if _, ok := root.children[animal.IsMammal]; !ok {
            root.children[animal.IsMammal] = &node{}
        }
        root.children[animal.IsMammal].data = append(root.children[animal.IsMammal].data, animal)
    }
    // Split each child node based on other characteristics
    for _, child := range root.children {
        child.split = "Legs"
        child.children = make(map[interface{}]*node)
        for _, animal := range child.data {
            if _, ok := child.children[animal.Legs]; !ok {
                child.children[animal.Legs] = &node{}
            }
            child.children[animal.Legs].data = append(child.children[animal.Legs].data, animal)
        }
    }
    return root
}
func classifyAnimal(animal Animal, node *node) bool {
    // If leaf node, return classification
    if len(node.children) == 0 {
        return node.classification
    }
    // Traverse tree based on animal characteristics
    switch node.split {
    case "IsMammal":
        if animal.IsMammal {
            return classifyAnimal(animal, node.children[true])
        } else {
            return classifyAnimal(animal, node.children[false])
        }
    case "Legs":
        if _, ok := node.children[animal.Legs]; ok {
            return classifyAnimal(animal, node.children[animal.Legs])
        } else {
            return false
        }
    }
    return false
}
type node struct {
    split         string
    children      map[interface{}]*node
    data          []Animal
    classification bool
}
```
In this example, we first create a dataset containing information on various animals. We then build a decision tree using the `buildDecisionTree` function, which splits the dataset based on whether or not the animal is a mammal and then further splits each child node based on the number of legs. We then test the decision tree using the `classifyAnimal` function, which traverses the tree based on the characteristics of the given animal and returns whether or not it is classified as a mammal.

