function generateBreaks(num) {
  if (num < 1 || num > 10) {
    return "Error: Number of breaks must be between 1 and 10";
  }
  var breaks = "";
  for (var i = 0; i < num; i++) {
    breaks += "<br>";
  }
  return breaks;
}
function checkOrder(num) {
  var arr = num.toString().split(",");
  if (arr.length > 1) {
    for (var i = 1; i < arr.length; i++) {
      if (arr[i] > arr[i-1]) {
        return "Error: Numbers must be entered in either ascending or descending order";
      }
    }
  }
  return generateBreaks(num);
}
```
