		const curHr = today.getHours();
		let timeOfDay;
		if (curHr < 12) {
			timeOfDay = "morning";
		} else if (curHr < 18) {
			timeOfDay = "afternoon";
		} else {
			timeOfDay = "evening";
		}
		const greeting = {
			"morning": "Good morning",
			"afternoon": "Good afternoon",
			"evening": "Good evening"
		}
