bool isMonosyllabic(string word) {
    int count = 0;
    for (int i = 0; i < word.length(); i++) {
        if (word[i] == 'a' || word[i] == 'e' || word[i] == 'i' || word[i] == 'o' || word[i] == 'u') {
            count++;
        }
    }
    if (count == 1) {
        return true;
    }
    else {
        return false;
    }
}
bool hasFinalSound(string word) {
    string finalSound = "r";
    if (word.length() >= finalSound.length()) {
        return (0 == word.compare(word.length() - finalSound.length(), finalSound.length(), finalSound));
    }
    else {
        return false;
    }
}
bool hasSpecificSound(string word) {
    string specificSound = "iver";
    if (word.length() >= specificSound.length()) {
        return (0 == word.compare(word.length() - specificSound.length(), specificSound.length(), specificSound));
    }
    else {
        return false;
    }
